/*
 * A107573  a(n)=least sidelength of n-th triangle listed at A107572.
 * https://oeis.org/A107573
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by enumerating integer‑sided scalene triangles
   sorted by perimeter, then by the smallest side, then by the second side.
   a(n) is the smallest side of the n-th triangle in that ordering. */
#include <stdbool.h>   // for bool, not used directly

seq_t a(idx_t n)
{
    idx_t count = 0;
    for (idx_t p = 9; ; ++p) {            /* minimal perimeter is 9 (2,3,4) */
        idx_t a_max = (p - 3) / 3;        /* maximal a: a+b+c = p, a < b < c */
        for (idx_t a = 2; a <= a_max; ++a) {
            /* lower bound on b:
               - must be > a
               - must satisfy 2*(a+b) > p   -->  b > (p-2*a)/2   */
            idx_t low_b = a + 1;
            idx_t t = (p > 2 * a) ? ((p - 2 * a) / 2) : 0;
            if (t + 1 > low_b)
                low_b = t + 1;

            /* upper bound on b:
               - must be < (p - a)/2   (since c = p - a - b > b)   */
            idx_t upper_b = (p - a - 1) / 2;
            if (low_b > upper_b)
                continue;

            for (idx_t b = low_b; b <= upper_b; ++b) {
                ++count;
                if (count == n)
                    return (seq_t)a;
            }
        }
    }
    return 0;   /* unreachable */
}
